rownum = 0;
/**
 * @method
 * @name file_browse
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.file_browse = function() {
    //alert(rownum);
    if (scwin.rownum > 4) {
        alert("파일업로드는 5개까지만 가능합니다.");
        return;
    } else {
        scwin.fn_addRow();
    }
};



//파일명추출
/**
 * @method
 * @name fn_getFileNm
 * @description desc
 * @param {string} rn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm = function(rn) {
    var objFile = $("input[name='attachFiles[" + rn + "]']");
    var temp = $("input[name='attachFiles[" + rn + "]']").val(); //원본파일
    var fullName = temp.substring(temp.lastIndexOf('\\') + 1); //파일명 확장자포함
    var extension = fullName.substring(fullName.lastIndexOf('.') + 1); //확장자
    var onlyName = fullName.substring(0, fullName.lastIndexOf('.')); //파일명만

    // DART Viewer 지원 중지로 dsd 파일 업로드 불가 2024.05.16 by 김효준
    var extList = new Array("hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "gif", "jpg", "jpeg", "bmp", "tif", "txt", "drt", "png");
    var fileChk = false;
    for (var i = 0; i < extList.length; i++) {
        if (extList[i] == extension.toLowerCase()) {
            fileChk = true;
            break;
        }
    }
    if (!fileChk) {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='attachFiles[" + rn + "]']").val("");
        $("input[name='attach_file_nm[" + rn + "]']").val("");
        objFile.replaceWith(objFile.clone(true));
        return;
    }

    //파일명 길이체크
    if (onlyName.length > 100) {
        alert("파일명이 100자를 초과하는 파일은 첨부 할 수 없습니다.");
        $("input[name='attach_file_nm[" + rn + "]']").val("");
        $("input[name='attach_file_nm[" + rn + "]']").focus();
        objFile.replaceWith(objFile.clone(true));
        return;
    }

    // 중복파일 체크.
    var fileCnt = $("input[name=file_coment]").length;
    for (var i = 0; i < fileCnt; i++) {
        if (fullName == $("input[name='attach_file_nm[" + i + "]']").val()) {
            alert("이미 첨부된 파일입니다.");
            $("input[name='attach_file_nm[" + rn + "]']").val("");
            objFile.replaceWith(objFile.clone(true));
            return;
        }
    }
    $("input[name='attach_file_nm[" + rn + "]']").val(fullName);
};



//파일명 추출후 업로드 가능 확장자인지 확인.
/**
 * @method
 * @name fn_getFileNm1
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm1 = function() {
    var temp = $("input[name='batScdaplExcelFiles[0]']").val();
    $("input[name='batScdaplExcelFilesNm[0]']").val(temp.substring(temp.lastIndexOf('\\') + 1));
    var file_name = temp.substring(temp.lastIndexOf('\\') + 1);
    var file = file_name.split(".");
    var extList = new Array("xls", "xlsx");
    var fileChk = 0;
    for (var i = 0; i < extList.length; i++) {
        if (file[file.length - 1].toLowerCase() == extList[i]) fileChk = fileChk + 1;
    }
    if (fileChk == 0) {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='batScdaplExcelFiles[0]']").val("");
        $("input[name='batScdaplExcelFilesNm[0]']").val("");
    }
};




