//라디오버튼 text타입으로 값전달
/**
 * @method
 * @name fn_setAttach_chk
 * @description desc
 * @param {string} div desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setAttach_chk = function(div, val) {
    var frm = document.SendForm;
    if (scwin.rownum <= 1) {
        frm.attach_file_tp_cd.setValue(val);
    } else {
        frm.attach_file_tp_cd[div].setValue(val);
    }
};



//Row 삭제
/**
 * @method
 * @name fn_delRow
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_delRow = function() {
    var rowPlus = document.getElementById("tbl_file");
    var chk_num = 0;

    //alert(rownum);

    if (scwin.rownum > 0) {
        $i = 0;
        $('input[name=chk]').each(function() {
            //alert($i);
            if ($(this).is(":checked")) {
                chk_num++;
                rowPlus.deleteRow($i);
                scwin.rownum--;
                $i = $i - 1;
                if (scwin.rownum == 0) {
                    var tr;
                    var th;
                    var td;
                    var newRowNum = scwin.rownum + 1;
                    tr = rowPlus.insertRow();
                    tr.addClass("first");
                    td = tr.insertCell();
                    td.colSpan = "4";
                    td.addClass("first txc");
                    td.innerHTML = "첨부파일이 없습니다.";
                    td.appendChild(td);
                }
                //input file 내용지우기

                /*var temp = $('input[name=attachFile]');
                temp[$i-1].select();
                document.selection.clear();*/
            }
            $i = $i + 1;
        });
        if (chk_num == 0) {
            alert("선택된 행이 없습니다.");
            return;
        }
        scwin.reNames();
    } else if (scwin.rownum < 1) {
        alert("삭제 할 행이 없습니다.");
    }
};
/**
 * @method
 * @name reNames
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.reNames = function() {
    $.each($("input:file"), function(i) {
        //alert('1_'+i);
        $(this).attr("name", "attachFiles[" + i + "]");
        $(this).attr("onchange", "fn_getFileNm(" + i + ");");
    });
    $.each($("#SendForm").find("input[name*=attach_file_nm]"), function(i) {
        //alert('2_'+i);
        $(this).attr("name", "attach_file_nm[" + i + "]");
    });
    $.each($("#tbl_file tr"), function(i) {
        //alert('3_'+i);
        $(this).find("input:radio").attr("name", "attach_chk" + i);
        $(this).find("input:radio").attr("onclick", "fn_setAttach_chk(" + i + ", this.value)");
    });
};



