/**
 * @method
 * @name selectAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.selectAll = function() {
    var checked = $("#chk_all").attr("checked");
    $.each($("#SendForm").find("input[name='chk']"), function(i) {
        var subChecked = $(this).attr("checked");
        if (subChecked != checked) {
            $(this).click();
        }
    });
    $.each($("#fileUploadList").find("input[name='chk']"), function(i) {
        var subChecked = $(this).attr("checked");
        if (subChecked != checked) {
            $(this).click();
        }
    });
};




//저장시 파일 추가되어 있는지 확인
/**
 * @method
 * @name checkLineFile
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkLineFile = function() {
    for (var i = 0; i < 5; i++) {
        var fi = $("input[name='attach_file_nm[" + i + "]']").val();
        if (fi == "") {
            alert("첨부파일이 없습니다.\n첨부할 파일이 없으면 파일첨부를 삭제해 주세요");
            $("input[name='attach_file_nm[" + i + "]']").focus();
            return false;
        }
    }
    return true;
};



// 전체 첨부파일의 크기를 MB로 리턴한다.
/**
 * @method
 * @name sumAttachedFilesSize
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.sumAttachedFilesSize = function() {
    // 파일타입 객체 전체 select
    var all_files = $("input[type='file']");
    var totalSize = 0;
    for (var i = 0; i < all_files.length; i++) {
        if (all_files[i].files[0] != undefined) {
            var fileName = all_files[i].files[0].name;
            var fileSize = all_files[i].files[0].size;
            var fileExtension = fileName.split('.').pop();
            totalSize += fileSize;
        }
    }
    //alert("첨부파일 전체 크기 = " + (totalSize/(1024*1024)).toFixed(2));
    return (totalSize / (1024 * 1024)).toFixed(2);
};
